fn shared_finish_inductive(pre: Self, post: Self, r: int) {
    assert forall |x: int| 0 <= x < pre.rc_width implies
        post.ref_counts.index(x) ==
            post.shared_pending.count(x) as int +
            Self::filter_r(post.shared_guard, x).len() as int
    by {
        assert(pre.shared_pending.count(x) > 0 ==> x == r);
        assert(post.shared_pending.count(x) ==
            if x == r { pre.shared_pending.count(x) - 1 } else { pre.shared_pending.count(x) });
        assert(Self::filter_r(post.shared_guard, x).len() ==
            if x == r { Self::filter_r(pre.shared_guard, x).len() + 1 }
            else { Self::filter_r(pre.shared_guard, x).len() });
        assert(pre.ref_counts.index(x) ==
            pre.shared_pending.count(x) as int +
            Self::filter_r(pre.shared_guard, x).len() as int);
    }
}

